function sameAfterBackspaces(a: string, b: string): boolean {
  const replay = (s: string): string => {
    const out: string[] = [];
    for (const c of s) {
      if (c === "#") out.pop();
      else out.push(c);
    }
    return out.join("");
  };
  return replay(a) === replay(b);
}

