    def sameAfterBackspaces(self, a: str, b: str) -> bool:
        def replay(s):
            out = []
            for c in s:
                if c == "#":
                    if out:
                        out.pop()
                else:
                    out.append(c)
            return out
        return replay(a) == replay(b)

