function sameAfterBackspaces(a: string, b: string): boolean {
  // moves k left to the next surviving character, or to -1
  const nextKept = (s: string, k: number): number => {
    let skip = 0;
    while (k >= 0) {
      if (s[k] === "#") skip++;
      else if (skip > 0) skip--;
      else break;
      k--;
    }
    return k;
  };
  let i = a.length - 1, j = b.length - 1;
  while (true) {
    i = nextKept(a, i);
    j = nextKept(b, j);
    if (i < 0 || j < 0) return i < 0 && j < 0;
    if (a[i] !== b[j]) return false;
    i--;
    j--;
  }
}

